import sys

s = sys.stdin.readline().strip() + ','
names = []
vals = []
name = ''
sign = ''
num = ''
for c in s:
    if c == ' ':
        continue
    if c == ',':
        v = int(num)
        if sign == '-':
            v = -v
        found = False
        for j in range(len(names)):
            if names[j] == name:
                vals[j] += v
                found = True
        if not found:
            names.append(name)
            vals.append(v)
        name = ''
        sign = ''
        num = ''
    elif c == '+' or c == '-':
        sign = c
    elif '0' <= c <= '9':
        num += c
    else:
        name += c
for j in range(len(names)):
    print(names[j], vals[j])
